// Hand-written `kysely` stub for the flowatlas fixture suite. It declares only what
// `fixtures/nest-kysely/src` touches, shaped like the real library so that
// `resolveTypeOrigin` sees the same thing it sees on a real repo.
//
// Two things about this shape are the reason the fixture exists. The connection is
// `Kysely<Schema>`, and the type argument is the whole database rather than one table,
// so a reader that treats a type argument as an entity puts the name of the schema type
// on every query as though it were a table. And every query starts by naming its table
// in the first argument of one of four calls, which is where the name has to be read
// from instead.

export interface Selection<Row> {
  selectAll(): Selection<Row>;
  select(column: string): Selection<Row>;
  where(column: string, operator: string, value: unknown): Selection<Row>;
  innerJoin(table: string, left: string, right: string): Selection<Row>;
  as(alias: string): Selection<Row>;
  orderBy(column: string): Selection<Row>;
  execute(): Promise<Row[]>;
  executeTakeFirst(): Promise<Row | undefined>;
}

export interface Insertion<Row> {
  values(row: Record<string, unknown>): Insertion<Row>;
  onConflict(build: (builder: unknown) => unknown): Insertion<Row>;
  returningAll(): Insertion<Row>;
  execute(): Promise<Row[]>;
}

export interface Update<Row> {
  set(row: Record<string, unknown>): Update<Row>;
  where(column: string, operator: string, value: unknown): Update<Row>;
  execute(): Promise<Row[]>;
}

export interface Deletion<Row> {
  where(column: string, operator: string, value: unknown): Deletion<Row>;
  execute(): Promise<Row[]>;
}

export interface ExpressionBuilder<Schema> {
  selectFrom(table: string): Selection<unknown>;
}

export declare class Kysely<Schema> {
  selectFrom(
    table: string | ((eb: ExpressionBuilder<Schema>) => Selection<unknown>),
  ): Selection<unknown>;
  insertInto(table: string): Insertion<unknown>;
  updateTable(table: string): Update<unknown>;
  deleteFrom(table: string): Deletion<unknown>;
  transaction(): { execute<T>(run: (tx: Transaction<Schema>) => Promise<T>): Promise<T> };
  destroy(): Promise<void>;
}

export declare class Transaction<Schema> extends Kysely<Schema> {}
